document.addEventListener("DOMContentLoaded",()=>{const n=document.getElementById("ask-title"),e=document.getElementById("related-questions"),s=document.getElementById("related-list");if(!n||!e||!s)return;let i=null;n.addEventListener("input",()=>{clearTimeout(i);const l=n.value.trim();if(l.length<8){e.classList.add("hidden");return}i=setTimeout(async()=>{try{const a=await(await fetch("/api/related_questions.php?q="+encodeURIComponent(l))).json();if(!a.results||!a.results.length){e.classList.add("hidden");return}s.innerHTML="",a.results.forEach(d=>{const t=document.createElement("a");t.href="/question.php?slug="+encodeURIComponent(d.slug),t.target="_blank",t.className="block text-sm text-indigo-600 hover:underline",t.textContent=`${d.title} (${d.answer_count} answers)`,s.appendChild(t)}),e.classList.remove("hidden")}catch(o){e.classList.add("hidden")}},500)})});
